  ,high_latitude_runoff_influx: boundedOperationalMetric({ metric_id: 'arctic_river_discharge_anomaly', metric_name: 'Arctic river-discharge anomaly', unit: 'cubic kilometres per period or cubic metres per second with gauge network and baseline stated', geography: 'named Arctic river, gauged watershed, or declared pan-Arctic aggregation', cadence: 'daily gauge data with monthly, seasonal, and annual summaries', observation_time_field: 'river_discharge_period', source_id: 'noaa_arctic_report_card', transformation: 'Retain gauge and basin identities, coverage period, discharge method, ice effects, missing data, regulated flow, aggregation, freshet timing, and baseline.', uncertainty: 'Gauge coverage, ice conditions, rating curves, reservoir operations, missing months, ungauged basins, and differing baselines affect totals.', threshold_provenance: 'Use the named NOAA Arctic Report Card river set and reference period; high influx has no universal threshold.', failure_behavior: 'Do not infer Arctic Ocean salinity, circulation, or cause from discharge alone.' })
