  ,vegetational_windbreak_removals: boundedOperationalMetric({ metric_id: 'agricultural_windbreak_cover_loss', metric_name: 'Agricultural windbreak cover loss', unit: 'metres or hectares removed with porosity, height, orientation, field boundary, and date stated', geography: 'named farm, field boundary, shelterbelt, or agricultural landscape', cadence: 'disturbance event with annual mapping', observation_time_field: 'windbreak_assessment_date', source_id: 'usda_nrcs_soil_risks_and_hazards', transformation: 'Retain mapped line or area, vegetation type, height and porosity where available, removal versus mortality, field orientation, wind and soil context, imagery dates, and uncertainty.', uncertainty: 'Image resolution, seasonal foliage, pruning, mortality, replanting, wind direction, soil cover, and incomplete historical mapping affect interpretation.', threshold_provenance: 'Use mapped repeat observations and an NRCS-aligned windbreak boundary; loss does not itself quantify erosion.', failure_behavior: 'Do not infer soil loss or evapotranspiration change from removal area without field observations.' })
